package org.beyondlight;
import java.util.*;
/** Local finite-difference sensitivity, covariance-aware linear propagation, bounded sweeps and seeded Monte Carlo. */
public final class Uncertainty {
 public record Propagated(double value,double sigma,List<String>variables,double[]sensitivities,String method,String assumptions){}
 public record MonteCarlo(double mean,double standardDeviation,double lower95,double upper95,int samples,int rejected,long seed){}
 public record Sweep(String variable,List<Double>values,List<Double>outputs,int points,String method,String limitations){}
 private Uncertainty(){}
 public static Propagated propagate(String e,Map<String,Double>m,Map<String,Double>s){return propagate(e,m,s,Map.of());}
 /** correlations use canonical unordered keys "a:b"; if any are supplied every pair must be specified. */
 public static Propagated propagate(String expression,Map<String,Double>means,Map<String,Double>sigma,Map<String,Double>correlations){List<String>names=new ArrayList<>(means.keySet());Collections.sort(names);double y=Symbolic.evaluate(expression,means);double[]g=new double[names.size()],sig=new double[names.size()];for(int i=0;i<names.size();i++){String k=names.get(i);sig[i]=sigma.getOrDefault(k,0d);if(sig[i]<0||!Double.isFinite(sig[i]))throw new IllegalArgumentException("standard deviations must be finite and nonnegative");double h=Math.max(Math.abs(means.get(k))*1e-6,1e-7);g[i]=(eval(expression,means,k,h)-eval(expression,means,k,-h))/(2*h);if(!Double.isFinite(g[i]))throw new IllegalArgumentException("sensitivity is nonfinite for "+k);}double variance=0;boolean corr=!correlations.isEmpty();for(int i=0;i<names.size();i++)for(int j=0;j<names.size();j++){double rho=i==j?1:(corr?correlations.getOrDefault(key(names.get(i),names.get(j)),Double.NaN):0);if(corr&&i!=j&&Double.isNaN(rho))throw new IllegalArgumentException("correlation missing for pair "+key(names.get(i),names.get(j)));if(!Double.isFinite(rho)||Math.abs(rho)>1)throw new IllegalArgumentException("correlations must be finite and within [-1,1]");if(i!=j&&!Objects.equals(correlations.get(key(names.get(i),names.get(j))),correlations.get(key(names.get(j),names.get(i))))&&correlations.containsKey(key(names.get(j),names.get(i))))throw new IllegalArgumentException("correlation matrix must be symmetric");variance+=g[i]*g[j]*sig[i]*sig[j]*rho;}if(variance< -1e-10*Math.max(1,Math.abs(y)))throw new IllegalArgumentException("supplied correlation matrix yields negative variance (not positive semidefinite)");return new Propagated(y,Math.sqrt(Math.max(0,variance)),List.copyOf(names),g,corr?"first-order Jacobian with supplied correlations":"first-order Jacobian with explicit independent-input assumption",corr?"Input correlation coefficients provided; linearized model; model uncertainty omitted.":"Unknown correlations were not inferred; zero covariance is assumed only under the explicitly selected independent-input method. Model uncertainty omitted.");}
 public static List<Map<String,Object>>sensitivity(String e,Map<String,Double>m){Map<String,Object>out=new TreeMap<>();double y=Symbolic.evaluate(e,m);for(String k:new TreeSet<>(m.keySet())){double h=Math.max(Math.abs(m.get(k))*1e-6,1e-7),d=(eval(e,m,k,h)-eval(e,m,k,-h))/(2*h);Map<String,Object>x=new LinkedHashMap<>();x.put("derivative",d);x.put("relative_sensitivity",Math.abs(y)>1e-300?d*m.get(k)/y:null);out.put(k,x);}List<Map<String,Object>>a=new ArrayList<>();for(var kv:out.entrySet()){Map<String,Object>m2=new LinkedHashMap<>();m2.put("variable",kv.getKey());m2.putAll((Map<String,Object>)kv.getValue());a.add(m2);}return a;}
 public static Sweep sweep(String e,Map<String,Double>base,String variable,double min,double max,int points){if(points<2||points>10000||!Double.isFinite(min)||!Double.isFinite(max)||max<min)throw new IllegalArgumentException("sweep needs 2..10,000 points and finite ordered limits");List<Double>x=new ArrayList<>(),y=new ArrayList<>();for(int i=0;i<points;i++){double v=min+(max-min)*i/(points-1.0);x.add(v);y.add(eval(e,base,variable,v-base.getOrDefault(variable,0d)));}return new Sweep(variable,List.copyOf(x),List.copyOf(y),points,"deterministic uniform parameter sweep", "One variable varied; all others held at supplied values; model uncertainty not included.");}
 private static String key(String a,String b){return a.compareTo(b)<0?a+":"+b:b+":"+a;}private static double eval(String e,Map<String,Double>m,String k,double d){Map<String,Double>x=new HashMap<>(m);x.put(k,x.getOrDefault(k,0d)+d);return Symbolic.evaluate(e,x);}
 public static MonteCarlo monteCarlo(String expression,Map<String,Double>mean,Map<String,Double>sigma,int n,long seed){if(n<1||n>1_000_000)throw new IllegalArgumentException("Monte Carlo samples must be 1..1,000,000");Symbolic.Node tree=Symbolic.parse(expression);Random r=new Random(seed);double avg=0,m2=0;int good=0,bad=0;double[]sample=new double[n];List<String>names=new ArrayList<>(mean.keySet());Collections.sort(names);for(int i=0;i<n;i++){Map<String,Double>x=new HashMap<>();for(String k:names){double s=sigma.getOrDefault(k,0d);if(s<0||!Double.isFinite(s))throw new IllegalArgumentException("invalid sigma");x.put(k,mean.get(k)+s*r.nextGaussian());}try{double y=Symbolic.evaluate(tree,x);sample[good]=y;good++;double d=y-avg;avg+=d/good;m2+=d*(y-avg);}catch(IllegalArgumentException ex){bad++;}}if(good<2)throw new IllegalArgumentException("fewer than two valid Monte Carlo samples; domain failure");Arrays.sort(sample,0,good);return new MonteCarlo(avg,Math.sqrt(m2/(good-1)),sample[(int)Math.floor(.025*(good-1))],sample[(int)Math.floor(.975*(good-1))],n,bad,seed);}
}
